import type { NextRequest } from 'next/server'

export async function middleware(request: NextRequest) {
  // Skip middleware for the env-check page itself to avoid infinite redirects
  if (request.nextUrl.pathname === '/env-check') {
    return NextResponse.next()
  }

  // Skip middleware for API routes, static files, and Next.js internals
  if (
    request.nextUrl.pathname.startsWith('/api/') ||
    request.nextUrl.pathname.startsWith('/_next/') ||
    request.nextUrl.pathname.includes('.')
  ) {
    return NextResponse.next()
  }

  // Simplified middleware - just pass through requests
  // Environment validation will be handled in the pages themselves
  return NextResponse.next()
}

